import{_ as t,o as a,c as o,a5 as d}from"./chunks/framework.DSg0KOwT.js";const g=JSON.parse('{"title":"Visual system and templating","description":"","frontmatter":{},"headers":[],"relativePath":"contributor-guide/architecture/board-widgets/visual-system-and-templating.md","filePath":"contributor-guide/architecture/board-widgets/visual-system-and-templating.md"}'),i={name:"contributor-guide/architecture/board-widgets/visual-system-and-templating.md"};function s(n,e,c,r,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="visual-system-and-templating" tabindex="-1">Visual system and templating <a class="header-anchor" href="#visual-system-and-templating" aria-label="Permalink to &quot;Visual system and templating&quot;">​</a></h1><p>The styling system the board widgets share and the rules that keep their templating free of injected markup.</p><h2 id="visual-system" tabindex="-1">Visual system <a class="header-anchor" href="#visual-system" aria-label="Permalink to &quot;Visual system&quot;">​</a></h2><p>Tailwind CSS v4 + shadcn/ui (Base UI primitives). The design tokens (colors, including the Trace palette, see <code>docs/DESIGN.md</code>) are defined as CSS variables in an <code>@theme inline</code> block and consumed via Tailwind utility classes; there is no hand-authored BEM CSS. Theme polarity: dark = bare <code>:root</code> (no attribute), light = <code>:root[data-theme=&quot;light&quot;]</code>, toggled by <code>src/theme/ThemeProvider.tsx</code> and persisted to <code>localStorage</code>. <code>index.html</code>&#39;s inline FOUC-prevention script runs before React mounts. Mono is the typeface for numerics (<code>--font-mono</code>), applied via a <code>.num</code>-equivalent Tailwind utility per call site rather than one global class. Charts are Recharts (<code>src/view/charts/ChartTheme.tsx</code>&#39;s <code>CHART_COLORS</code>, read from the same CSS tokens). React re-renders on theme toggle, so chart colors update live with the theme. <code>ChartFrame</code> can also expose the underlying rows through a toggleable accessible table and copy them to the clipboard as TSV.</p><h2 id="spacing-roles" tabindex="-1">Spacing roles <a class="header-anchor" href="#spacing-roles" aria-label="Permalink to &quot;Spacing roles&quot;">​</a></h2><p>Spacing uses five named roles on the 4px scale, defined in the <code>@theme</code> block of <code>src/index.css</code>. Each role is a Tailwind spacing key, so it works in any spacing utility (<code>mt-label</code>, <code>space-y-para</code>, <code>gap-card</code>) and as <code>var(--spacing-label)</code> in CSS.</p><table tabindex="0"><thead><tr><th>Role</th><th>Size</th><th>Use</th></tr></thead><tbody><tr><td><code>tight</code></td><td>4px</td><td>A title and its caption, or a label and its figure</td></tr><tr><td><code>label</code></td><td>8px</td><td>An eyebrow or heading and the content it names</td></tr><tr><td><code>para</code></td><td>8px</td><td>One paragraph and the next in a single block</td></tr><tr><td><code>card</code></td><td>16px</td><td>One block and the next inside a card</td></tr><tr><td><code>section</code></td><td>24px</td><td>One section and the next</td></tr></tbody></table><p><code>card</code> equals the default <code>Card</code>&#39;s <code>--card-spacing</code>. Use <code>pt-(--card-spacing)</code> inside a card so a <code>size=&quot;sm&quot;</code> card keeps its 12px.</p><p>Rules for a spacing change:</p><ul><li>Do not set a margin on a class in <code>src/theme/*.css</code> that components also space with a utility. Those files are not in a cascade layer, so a margin there beats <code>mt-*</code>, <code>mb-*</code> and <code>space-y-*</code> on the same element.</li><li>Do not put a <code>gap</code> on a <code>Collapsible</code>: a closed panel keeps the gap. The open body and the collapsed summary carry their own top padding.</li><li>Do not use a negative margin for rhythm.</li></ul><h2 id="templating-xss-safe" tabindex="-1">Templating (XSS-safe) <a class="header-anchor" href="#templating-xss-safe" aria-label="Permalink to &quot;Templating (XSS-safe)&quot;">​</a></h2><p>JSX auto-escapes every interpolated value by default. No <code>.innerHTML</code> assignment exists anywhere in the view layer (the one <code>dangerouslySetInnerHTML</code>, shadcn&#39;s <code>ChartStyle</code> in <code>src/components/ui/chart.tsx</code>, only writes CSS variables from the static chart config).</p><p>One Base UI-specific gotcha: <code>WidgetCard.tsx</code> passes <code>aria-expanded={String(open) as &#39;true&#39; | &#39;false&#39;}</code> rather than the raw boolean, because Base UI&#39;s <code>Collapsible.Trigger</code> otherwise overrides a boolean <code>aria-expanded</code> prop with its own internal state via prop merging. The explicit <code>String()</code> cast keeps the rendered attribute in sync with this app&#39;s own <code>open</code> state.</p><h2 id="tag-badge-anatomy" tabindex="-1">Tag badge anatomy <a class="header-anchor" href="#tag-badge-anatomy" aria-label="Permalink to &quot;Tag badge anatomy&quot;">​</a></h2><p><code>TagBadge</code> (<code>src/view/ImpactBadge.tsx</code>) renders the impact dot and the ALL-CAPS tag as one pill built from two abutting halves:</p><ul><li>The dot+tag <code>Badge</code>, rounded on its left only when the guide link follows (at Advanced density).</li><li>The guide <code>&lt;a&gt;</code>, rounded on the right, immediately after it.</li></ul><p>The halves are siblings, never one <code>&lt;a&gt;</code> nested inside another: nested anchors are invalid HTML, and a pill-wide anchor would need a second link inside it. The guide link is hand-styled rather than built from <code>Badge</code>, because <code>Badge</code>&#39;s <code>overflow-hidden</code> would clip the link&#39;s <code>tap-target-comfortable</code> overlay. That overlay deliberately paints outside the link&#39;s visual bounds to reach a touch-friendly size without growing the pill.</p>',17)])])}const u=t(i,[["render",s]]);export{g as __pageData,u as default};
